<?php use App\Core\View; $emoji=['Happy'=>'😊','Sad'=>'😔','Excited'=>'🤩','Anxious'=>'😟','Calm'=>'😌','Angry'=>'😠','Grateful'=>'🙏','Tired'=>'😴','Stressed'=>'😣','Neutral'=>'😐']; ?>
<section class="page-heading"><div><p class="page-eyebrow">Private reflections</p><h1>Diary Journal</h1><p class="page-subtitle">A private space to capture your thoughts and track your mood.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= View::e($baseUrl) ?>/diary/calendar"><i class="bi bi-calendar3"></i> Calendar</a><a class="btn btn-primary" href="<?= View::e($baseUrl) ?>/diary/create"><i class="bi bi-plus-lg"></i> New Reflection</a></div></section><section class="filter-panel mb-4"><form method="get" class="row g-3 align-items-end"><div class="col-lg-4"><label class="form-label" for="search">Search reflections</label><input class="form-control" id="search" name="search" placeholder="Search reflections..." value="<?= View::e($filters['search']) ?>"></div><div class="col-lg-3"><label class="form-label" for="mood">Mood</label><select class="form-select" id="mood" name="mood"><option value="">All moods</option><?php foreach($moods as $m): ?><option value="<?= View::e($m) ?>" <?= $filters['mood']===$m?'selected':'' ?>><?= $emoji[$m] ?> <?= View::e($m) ?></option><?php endforeach; ?></select></div><div class="col-lg-3"><label class="form-label" for="sort">Sort</label><select class="form-select" id="sort" name="sort"><option value="newest" <?= $filters['sort']==='newest'?'selected':'' ?>>Newest first</option><option value="oldest" <?= $filters['sort']==='oldest'?'selected':'' ?>>Oldest first</option><option value="title" <?= $filters['sort']==='title'?'selected':'' ?>>Title A–Z</option></select></div><div class="col-lg-2"><div class="form-check mb-2"><input class="form-check-input" id="favorite" type="checkbox" name="favorite" value="1" <?= $filters['favorite']?'checked':'' ?>><label class="form-check-label" for="favorite">Favourites</label></div><button class="btn btn-outline-primary w-100"><i class="bi bi-funnel"></i> Apply</button></div></form></section><div class="row g-4"><div class="col-xl-9"><section class="diary-grid"><?php foreach($entries as $entry): ?><a class="content-card diary-card" href="<?= View::e($baseUrl) ?>/diary/view?id=<?= (int)$entry['entry_id'] ?>"><?php if($entry['is_favorite']): ?><i class="bi bi-star-fill fav-star"></i><?php endif; ?><h2><?= View::e($entry['title']) ?></h2><div class="diary-meta"><span class="mood-pill mood-<?= strtolower(View::e($entry['mood'])) ?>"><?= $emoji[$entry['mood']] ?> <?= View::e($entry['mood']) ?></span><span><i class="bi bi-calendar3"></i> <?= View::e(date('d M Y',strtotime($entry['entry_date']))) ?></span></div><p><?= View::e(mb_strimwidth($entry['content'],0,155,'…')) ?></p><small class="text-muted d-block mt-2">Mood score: <?= (int)$entry['mood_score'] ?>/10</small></a><?php endforeach; ?><?php if(!$entries): ?><div class="content-card empty-state" style="grid-column:1/-1"><div class="empty-icon"><i class="bi bi-journal-plus"></i></div><h3>No reflections found</h3><p>Write your first reflection and it will appear here.</p><a class="btn btn-primary" href="<?= View::e($baseUrl) ?>/diary/create">New Reflection</a></div><?php endif; ?></section></div><aside class="col-xl-3"><section class="content-card"><p class="card-kicker">Your journal</p><h2>Journal insights</h2><div class="row text-center my-3"><div class="col-6"><strong class="d-block fs-4"><?= (int)$insights['totals']['entries'] ?></strong><small class="text-muted">Reflections</small></div><div class="col-6"><strong class="d-block fs-4"><?= View::e($insights['totals']['average']) ?>/10</strong><small class="text-muted">Average mood</small></div></div><?php foreach(array_slice($insights['moods'],0,5) as $m): ?><div class="d-flex justify-content-between py-2 border-top"><span><?= $emoji[$m['mood']] ?> <?= View::e($m['mood']) ?></span><strong><?= (int)$m['count'] ?></strong></div><?php endforeach; ?></section></aside></div>
